param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('CustomFallbackOracle'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('CustomFallbackOracle')
function CustomType([string]$Direction){
 $base=[type]("System.Text.${Direction}Fallback");$replacement=[type]("System.Text.${Direction}ReplacementFallback");$buffer=[type]("System.Text.${Direction}FallbackBuffer");$builder=$module.DefineType('Custom'+$Direction+'Fallback',[Reflection.TypeAttributes]::Public,$base);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$text=$builder.DefineField('Replacement',[string],[Reflection.FieldAttributes]::Public);$maximum=$builder.DefineField('Maximum',[int],[Reflection.FieldAttributes]::Public);$calls=$builder.DefineField('FactoryCalls',[int],[Reflection.FieldAttributes]::Public);$reads=$builder.DefineField('MaximumCalls',[int],[Reflection.FieldAttributes]::Public)
 $attributes=[Reflection.MethodAttributes]'Public,Virtual,HideBySig';$getter=$builder.DefineMethod('get_MaxCharCount',$attributes-bor[Reflection.MethodAttributes]::SpecialName,[int],[type[]]@());$il=$getter.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$reads);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$reads);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$maximum);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($getter,$base.GetProperty('MaxCharCount').GetMethod)
 $factory=$builder.DefineMethod('CreateFallbackBuffer',$attributes,$buffer,[type[]]@());$il=$factory.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$text);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$replacement.GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod('CreateFallbackBuffer'));$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($factory,$base.GetMethod('CreateFallbackBuffer'));return $builder.CreateType()
}
$encoderType=CustomType 'Encoder';$decoderType=CustomType 'Decoder';$profiles=[Collections.Generic.List[object]]::new();$calls=0
foreach($bigEndian in @($false,$true)){foreach($maximum in @(-2147483648,-1,0,1,2,3,10,65535,1073741824,2147483647)){$encoder=[Activator]::CreateInstance($encoderType);$decoder=[Activator]::CreateInstance($decoderType);foreach($pair in @(@($encoderType,$encoder),@($decoderType,$decoder))){$pair[0].GetField('Replacement').SetValue($pair[1],'?');$pair[0].GetField('Maximum').SetValue($pair[1],[int]$maximum)};$owner=[Text.Encoding]([Text.UnicodeEncoding]::new($bigEndian,$true,$false)).Clone();$owner.EncoderFallback=$encoder;$owner.DecoderFallback=$decoder;$m=[Math]::Max(1,$maximum);$rows=[Collections.Generic.List[object]]::new()
 foreach($method in @('GetMaxByteCount','GetMaxCharCount')){$bound=if($method -eq 'GetMaxByteCount'){[long][Math]::Floor([int]::MaxValue/(2.0*$m))-1}else{2*([long][Math]::Floor([int]::MaxValue/[double]$m)-1)};$inputs=[Collections.Generic.SortedSet[int]]::new();foreach($n in @(-2147483648,-1,0,1,2,3,4,7,8,15,16,31,32,255,256,65535,65536,1073741822,1073741823,1073741824,2147483646,2147483647)){[void]$inputs.Add([int]$n)};foreach($delta in -3..3){$n=$bound+$delta;if($n -ge 0 -and $n -le [int]::MaxValue){[void]$inputs.Add([int]$n)}}
  foreach($n in $inputs){$encoder.MaximumCalls=0;$decoder.MaximumCalls=0;$encoder.FactoryCalls=0;$decoder.FactoryCalls=0;try{$value=if($method -eq 'GetMaxByteCount'){$owner.GetMaxByteCount($n)}else{$owner.GetMaxCharCount($n)};$result=[ordered]@{ok=$true;count=$value}}catch{$result=Failure-Of $_};$rows.Add([ordered]@{method=$method;input=$n;result=$result;encoderMaximumCalls=$encoder.MaximumCalls;decoderMaximumCalls=$decoder.MaximumCalls;encoderFactoryCalls=$encoder.FactoryCalls;decoderFactoryCalls=$decoder.FactoryCalls});$calls++}
 };$profiles.Add([ordered]@{bigEndian=$bigEndian;advertisedMaximum=$maximum;rows=$rows.ToArray()})
}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeCalls=$calls;profiles=$profiles.ToArray();qualification='NATIVE_SELECTED_UTF16_CUSTOM_FALLBACK_MAXIMUM_COUNT_AND_GETTER_CALLS_ONLY; NO_FULL_PARITY_OR_TASK_ACCEPTANCE'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF16 custom fallback max count capture: $calls calls"
